package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.cfg.TypeFactory;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitable;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.jsonschema.SchemaAware;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.ser.ResolvableSerializer;
import com.fasterxml.jackson.databind.ser.std.StdDelegatingSerializer;
import com.fasterxml.jackson.databind.util.Converter;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StdDelegatingSerializer_createContextual_TriageGen2Test {

    private SerializerProvider provider;
    private BeanProperty property;
    private TypeFactory typeFactory;
    private JavaType delegateType;
    private Converter<Object, ?> converter;

    @Before
    public void setUp() {
        provider = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        typeFactory = mock(TypeFactory.class);
        delegateType = mock(JavaType.class);
        converter = mock(Converter.class);

        when(provider.getTypeFactory()).thenReturn(typeFactory);
    }

    /**
     * Test case: _delegateSerializer is already set.
     * Should return 'this' (the current instance).
     */
    @Test
    public void testCreateContextual_DelegateAlreadySet() throws JsonMappingException {
        JsonSerializer<?> delSer = mock(JsonSerializer.class);

        // We use a subclass to inject the private fields via constructor/reflection or 
        // by extending since we cannot access private fields directly.
        // However, the prompt implies we are testing the method as provided.
        // Since we can't set private fields easily without reflection, we create a testable subclass.

        StdDelegatingSerializer<Object> serializer = new TestableStdDelegatingSerializer(delSer, null, converter);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertSame("Should return 'this' when delegate is already set and not contextual", serializer, result);
        verifyNoInteractions(provider);
    }

    /**
     * Test case: _delegateSerializer is null, _delegateType is null.
     * Should use converter to get type, then find serializer.
     */
    @Test
    public void testCreateContextual_NoDelegateNoType() throws JsonMappingException {
        when(converter.getOutputType(typeFactory)).thenReturn(delegateType);
        JsonSerializer<?> foundSer = mock(JsonSerializer.class);
        when(provider.findValueSerializer(delegateType)).thenReturn(foundSer);

        StdDelegatingSerializer<Object> serializer = new TestableStdDelegatingSerializer(null, null, converter);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame("Should not be 'this'", serializer, result);
        verify(converter).getOutputType(typeFactory);
        verify(provider).findValueSerializer(delegateType);
    }

    /**
     * Test case: _delegateSerializer is null, but _delegateType is set.
     * Should skip converter and find serializer directly.
     */
    @Test
    public void testCreateContextual_NoDelegateButTypeSet() throws JsonMappingException {
        JsonSerializer<?> foundSer = mock(JsonSerializer.class);
        when(provider.findValueSerializer(delegateType)).thenReturn(foundSer);

        StdDelegatingSerializer<Object> serializer = new TestableStdDelegatingSerializer(null, delegateType, converter);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame("Should not be 'this'", serializer, result);
        verify(converter, never()).getOutputType(any());
        verify(provider).findValueSerializer(delegateType);
    }

    /**
     * Test case: The found delegate is a ContextualSerializer.
     * Should call handleSecondaryContextualization.
     */
    @Test
    public void testCreateContextual_DelegateIsContextual() throws JsonMappingException {
        ContextualSerializer contextualSer = mock(ContextualSerializer.class);
        JsonSerializer<?> secondarySer = mock(JsonSerializer.class);

        when(converter.getOutputType(typeFactory)).thenReturn(delegateType);
        when(provider.findValueSerializer(delegateType)).thenReturn(contextualSer);
        when(provider.handleSecondaryContextualization(contextualSer, property)).thenReturn(secondarySer);

        StdDelegatingSerializer<Object> serializer = new TestableStdDelegatingSerializer(null, null, converter);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        // Since secondarySer != _delegateSerializer (which was null), it returns a new instance via withDelegate
        // We check if handleSecondaryContextualization was called.
        verify(provider).handleSecondaryContextualization(contextualSer, property);
        assertNotSame(serializer, result);
    }

    /**
     * Test case: The found delegate is NOT a ContextualSerializer.
     * Should return withDelegate result.
     */
    @Test
    public void testCreateContextual_DelegateNotContextual() throws JsonMappingException {
        JsonSerializer<?> nonContextualSer = mock(JsonSerializer.class);
        when(converter.getOutputType(typeFactory)).thenReturn(delegateType);
        when(provider.findValueSerializer(delegateType)).thenReturn(nonContextualSer);

        StdDelegatingSerializer<Object> serializer = new TestableStdDelegatingSerializer(null, null, converter);

        JsonSerializer<?> result = serializer.createContextual(provider, property);

        assertNotSame(serializer, result);
        verify(provider, never()).handleSecondaryContextualization(any(), any());
    }

    /**
     * Helper class to access/set protected fields for testing purposes.
     */
    private static class TestableStdDelegatingSerializer extends StdDelegatingSerializer<Object> {
        private JsonSerializer<?> forcedDelSer;
        private JavaType forcedType;
        private Converter<Object, ?> forcedConverter;

        public TestableStdDelegatingSerializer(JsonSerializer<?> delSer, JavaType type, Converter<Object, ?> conv) {
            super(delSer); // This sets _delegateSerializer via constructor if available
            this.forcedDelSer = delSer;
            this.forcedType = type;
            this.forcedConverter = conv;
        }

        // We override or use reflection to ensure the internal state matches the test scenario
        // Because StdDelegatingSerializer doesn't have a public constructor for all fields.
        // In a real scenario, we'd use ReflectionTestUtils or similar.
        @Override
        public JsonSerializer<?> createContextual(SerializerProvider provider, BeanProperty property) throws JsonMappingException {
            // Since we cannot change the private fields of the superclass directly without reflection,
            // we simulate the logic by using a custom implementation that mirrors the target method 
            // but uses our controlled fields.

            // Actually, for a professional test, we should use Reflection to set the private fields.
            try {
                setField("_delegateSerializer", forcedDelSer);
                setField("_delegateType", forcedType);
                setField("_converter", forcedConverter);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
            return super.createContextual(provider, property);
        }

        private void setField(String name, Object value) throws Exception {
            java.lang.reflect.Field field = StdDelegatingSerializer.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(this, value);
        }
    }
}
